using System.Windows; using TextBox=System.Windows.Controls.TextBox; using PasswordBox=System.Windows.Controls.PasswordBox; using StackPanel=System.Windows.Controls.StackPanel; using Image=System.Windows.Controls.Image; using TextBlock=System.Windows.Controls.TextBlock; using Button=System.Windows.Controls.Button; using Panel=System.Windows.Controls.Panel; using Control=System.Windows.Controls.Control; using TextWrapping=System.Windows.TextWrapping; namespace CloudServer; public sealed class FirstRunWindow:Window { readonly TextBox user=new(){Text="admin"},display=new(){Text="Administrator"}; readonly PasswordBox password=new(),confirm=new(); public string UserName=>user.Text.Trim(); public string DisplayName=>display.Text.Trim(); public string Password=>password.Password; public FirstRunWindow(){Title="i-NET-PROMO Cloudservice — Ersteinrichtung";Width=500;Height=520;WindowStartupLocation=WindowStartupLocation.CenterScreen;ResizeMode=ResizeMode.NoResize;var p=new StackPanel{Margin=new Thickness(36)};p.Children.Add(new Image{Source=BrandLogo.Image(),Height=85,Stretch=System.Windows.Media.Stretch.Uniform,HorizontalAlignment=HorizontalAlignment.Left});p.Children.Add(new TextBlock{Text="Administrator einrichten",FontSize=25,FontWeight=FontWeights.Bold,Margin=new Thickness(0,22,0,6)});p.Children.Add(new TextBlock{Text="Beim ersten Start muss ein eigener Administratorzugang erstellt werden.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,15)});Add(p,"Benutzername",user);Add(p,"Anzeigename",display);Add(p,"Passwort",password);Add(p,"Passwort wiederholen",confirm);var ok=new Button{Content="Server einrichten",Height=44,Margin=new Thickness(0,25,0,0)};ok.Click+=(_,__)=>{if(UserName.Length<3){System.Windows.MessageBox.Show("Der Benutzername muss mindestens 3 Zeichen lang sein.");return;}if(Password.Length<10){System.Windows.MessageBox.Show("Das Administratorpasswort muss mindestens 10 Zeichen lang sein.");return;}if(Password!=confirm.Password){System.Windows.MessageBox.Show("Die Passwörter stimmen nicht überein.");return;}DialogResult=true;};p.Children.Add(ok);Content=p;}static void Add(Panel p,string l,Control c){p.Children.Add(new TextBlock{Text=l,Margin=new Thickness(0,10,0,4)});c.Height=34;p.Children.Add(c);} }